from __future__ import annotations

import os
from pathlib import Path
from typing import Optional

from rasa.core.channels.voice_stream.call_recording.recording_encoder import (
    RECORDING_CONTENT_TYPE,
)
from rasa.core.channels.voice_stream.call_recording.storages.base import (
    RecordingReference,
    _object_key,
)
from rasa.core.config.available_endpoints import RecordingConfig
from rasa.core.persistor import AzurePersistor
from rasa.env import AZURE_ACCOUNT_KEY_ENV


class AzureRecordingStorage:
    """Azure Blob recording storage wrapper backed by the model persistor."""

    def __init__(self, config: RecordingConfig) -> None:
        if config.azure is None:
            raise ValueError(
                "Azure recording storage requires recordings.azure config."
            )
        account_key = os.environ.get(AZURE_ACCOUNT_KEY_ENV)
        if not account_key:
            raise ValueError(
                "Azure recording storage requires the "
                f"{AZURE_ACCOUNT_KEY_ENV} environment variable."
            )
        self._azure_config = config.azure
        self._persistor = AzurePersistor(
            azure_container=self._azure_config.container,
            azure_account_name=self._azure_config.account_name,
            azure_account_key=account_key,
            endpoint_url=self._azure_config.endpoint_url,
        )

    def upload(
        self, source: Path, conversation_id: str, call_id: str
    ) -> RecordingReference:
        """Upload the recording to Azure Blob Storage and return its location.

        Args:
            source: Path to the encoded recording file.
            conversation_id: Conversation identifier used in the blob name.
            call_id: Call identifier used in the blob name.

        Returns:
            Location of the uploaded recording.
        """
        key = _object_key(self._azure_config.prefix, conversation_id, call_id)
        self._persistor.persist_file(
            file_key=key,
            file_path=str(source),
            content_type=RECORDING_CONTENT_TYPE,
        )
        container = self._azure_config.container
        return RecordingReference(
            provider="azure",
            bucket=container,
            key=key,
            uri=_azure_blob_uri(
                account_name=self._azure_config.account_name,
                container=container,
                key=key,
                endpoint_url=self._azure_config.endpoint_url,
            ),
            content_type=RECORDING_CONTENT_TYPE,
        )


def _azure_blob_uri(
    account_name: str,
    container: str,
    key: str,
    endpoint_url: Optional[str] = None,
) -> str:
    """Build a blob URI for Azure or an S3-style Azure emulator endpoint."""
    if endpoint_url:
        return f"{endpoint_url.rstrip('/')}/{container}/{key}"
    return f"https://{account_name}.blob.core.windows.net/{container}/{key}"
